window.SEARCH_DOCS = [{"f":"01.html","n":1,"no":"01","t":"输入输出与评测机制","title":"输入输出与评测机制","core":"","lv":"入门","tg":["cin/cout","getline","整数范围","评测机制"],"hs":["本节出现的新函数 / 新语法（先看懂再用）","这一节最容易犯的 4 个错","自己动手复现","数学补给 · 为什么 int 的上限是 2.1×10⁹","举一反三 · 想清楚这些再往下走","自测：这 5 条都能答上来，才往下走","延伸阅读 / 参考","挑战题 · 再分肥宅水"],"b":[["b0",0,"本节出现的新函数 / 新语法（先看懂再用）"],["b1",-1,"cin（标准输入流） —— 最常用的读入方式：自动跳过空白，按变量类型解析每个数"],["b2",-1,"cout（标准输出流） —— 输出的主力：<< 把内容接进流里，用 \"\\n\" 结束一行"],["b3",-1,"ios::sync_with_stdio(false) 与 cin.tie(nullptr) —— 两行提速开关，输入量大时必写"],["b4",-1,"getline（读入一整行） —— 需要保留空格时唯一靠得住的工具"],["b5",-1,"先接受一个事实：评测机并不知道你想表达什么。它把你的程序输出的那串字节收下来，和标准答案的字节一个一个地比，完全相同才算通过。所以从今天起，每写一句输出都先问自己——这些字节会不会原封不动地出现在标准答案里？多一个空格、少一个换行、多一句“请输入”，都算错。"],["b6",-1,"这一节只做三件事：把输入输出的三个工具拆开看清楚；用一道最简的 A+B 把「读入 → 计算 → 输出 → 返回」跑一遍；最后弄明白为什么变量类型要跟着数据范围走。它们看起来简单，却是后面每一道题都要重复几十遍的动作。"],["b8",-1,"先把需求翻译成两个动作：取值、存变量"],["b9",-1,"需求其实只有两件事——从输入里取出一个值，把它放进一个变量。C++ 把这两件事压成一个运算符 >>，箭头朝变量，读法是「流里的东西流进变量」："],["b10",-1,"std::cin >> 变量1 >> 变量2 >> ...;"],["b11",-1,"这就是 cin 的全部签名。左边固定是流对象 std::cin，中间可以串任意多个 >>，右边每多写一个变量就多取一个值，取的顺序就是写的顺序。"],["b13",-1,"再把这句话拆成三段：流、运算符、变量各要求什么"],["b14",-1,"签名看懂了不等于会用。三个位置各有硬性要求，写错任何一处，读进来的东西都不可信："],["b15",-1,"组成"],["b16",-1,"含义 / 格式要求"],["b17",-1,"std::cin"],["b18",-1,"标准输入流对象，背后连着评测时喂给程序的那个输入文件。整个程序只有一个，直接用。"],["b19",-1,">>"],["b20",-1,"提取运算符，箭头朝变量：把流里的下一个“词”解析成右边变量的类型，再存进去。"],["b21",-1,"链式写法"],["b22",-1,"cin >> a >> b 从左往右算：先得 (cin >> a)，它返回 cin 本身，于是能接着 >> b。写成两条语句完全等价。"],["b23",-1,"跳过空白"],["b24",-1,"空格、Tab、换行都算分隔符，会被自动吃掉。所以“一行两个数”和“两行各一个数”读起来没有区别。"],["b25",-1,"类型决定解析"],["b26",-1,"给 int 读整数，给 double 读小数，给 char 读一个非空白字符。类型写错，读进来的东西就不可信。"],["b28",-1,"拿一段最小程序验证：读进来，再原样写出去"],["b29",-1,"语法对不对，跑一遍最清楚。这段程序读两个整数、输出它们的和，正好把「读—算—写」走一遍："],["b30",-1,"#include <iostream> using namespace std; int main() { int a, b; cin >> a >> b; // 一次取两个整数 cout << a + b << \"\\n\"; return 0; }"],["b31",-1,"把输入写成两行（先 2、换行、再 3），输出仍然是 5——这就验证了「跳过空白」这条规则：对 >> 来说，空格和换行是同一件东西。"],["b33",-1,"最后验证失败的那条路：类型不对、数据不够"],["b34",-1,"上面每一步都默认输入合法，而真正的坑全在失败路径上——cin 的失败是静默的，不抛异常、不打印任何东西："],["b35",-1,"变量类型必须和输入对得上：让 int 去读 abc，cin 会读失败，并且此后所有读入都静默失效——它不报错，只是把垃圾值留在变量里。"],["b36",-1,"cin 也不检查你读够了没有。数据比预期少时，后面的变量保持原值；局部变量是未初始化的，那是个随机数。"],["b38",-1,"需求 → 一句话：把值一个个接进输出流"],["b39",-1,"输出的动作和输入正好镜像：这次是「变量里的东西流进流里」，所以箭头朝流："],["b40",-1,"std::cout << 内容1 << 内容2 << ...;"],["b41",-1,"插入运算符能连着写任意多个，插进去什么类型就按什么类型转成字符，不必像 printf 那样先背一串格式符。"],["b43",-1,"拆开看：每个位置各管什么"],["b44",-1,"这几行里，前两行决定「写什么」，中间几行决定「写成什么样」，最后一行是数据量大时的提速开关："],["b45",-1,"组成"],["b46",-1,"含义 / 格式要求"],["b47",-1,"std::cout"],["b48",-1,"标准输出流对象。评测时它被接到一个文件上，程序结束后整份文件拿去和标准答案比对。"],["b49",-1,"<<"],["b50",-1,"插入运算符，箭头朝流：把右边的值转成字符送进去。它的方向和 >> 正好相反，别写反。"],["b51",-1,"\"\\n\""],["b52",-1,"一个换行字符。只往缓冲区塞一个字节，几乎不花时间，是最省事的收尾方式。"],["b53",-1,"endl"],["b54",-1,"换行 + 立刻刷新缓冲区。循环里用上百万次会慢一个数量级，多出来的开销全在 flush 上。"],["b55",-1,"fixed << setprecision(3)"],["b56",-1,"保留 3 位小数，需要 #include <iomanip>。不加 fixed 时，setprecision 数的是有效数字位数，完全不是一回事。"],["b57",-1,"提速两行"],["b58",-1,"输入输出量大于 10⁵ 次时，在 main 开头写 ios::sync_with_stdio(false); cin.tie(nullptr);：关掉 C 流与 C++ 流的同步、解除 cin 对 cout 的绑定。写一次就够，之后不要再混用 scanf / printf。"],["b60",-1,"拿一段最小程序验证：整数原样打、小数位要自己设"],["b61",-1,"这段程序一次演示三件事：整数照原样打、数字之间的空格要自己补、浮点的小数位要手动设："],["b62",-1,"#include <iostream> #include <iomanip> using namespace std; int main() { int a = 2, b = 3; cout << a << ' ' << b << \"\\n\"; // 输出 2 3 double ans = 500.0 / 3; cout << fixed << setprecision(3) << ans << \"\\n\"; // 输出 166.667 return 0; }"],["b64",-1,"两条边界：格式要自己说清楚、循环里别用 endl"],["b65",-1,"cout 不会替你补小数点、不会替你四舍五入，也不会替你判断该不该换行。两条最容易踩的规矩："],["b66",-1,"cout 不需要写格式符，插进去什么类型就按什么类型打；但也正因为如此，它不会替你补小数点、也不会替你四舍五入，格式必须自己说清楚。"],["b67",-1,"循环输出十万行以上时，一律用 \"\\n\"，不要用 endl。"],["b69",-1,"需求 → 换一个工具：按行读，不按词读"],["b70",-1,">> 的设计目标就是「跳过空白、取一个值」，它天生拿不到空格。要整行，得用一个独立的函数，把流和一个 string 交进去："],["b71",-1,"std::getline(std::cin, s);"],["b72",-1,"它是标准库里的普通函数，声明在 <string> 而不是 <iostream> 里——头文件少写一个，编译直接失败。"],["b74",-1,"拆开看：谁读、读进哪、读到哪停"],["b75",-1,"组成"],["b76",-1,"含义 / 格式要求"],["b77",-1,"std::getline"],["b78",-1,"独立的函数，声明在 <string> 里，不是 cin 的成员。所以头文件别只写 iostream。"],["b79",-1,"std::cin"],["b80",-1,"第一个参数：从哪个流读。考试里永远是 cin。"],["b82",-1,"第二个参数：一个 string 变量，整行内容写在这里，不含行末的换行符。"],["b83",-1,"读到哪里停"],["b84",-1,"一直读到 '\\n' 为止，并且把这个换行符从流里取走丢掉，所以下一次读入不会莫名其妙读到空行。"],["b85",-1,"和 cin >> 的区别"],["b86",-1,"cin >> 在第一个空白处就停，只拿到一个“词”；带空格的句子必须用 getline。"],["b87",-1,"要不要 ignore"],["b88",-1,"刚用 cin >> 读过一个数，流里还留着一个换行，getline 会立刻读到空串。中间补一句 cin.ignore(); 就对了。"],["b90",-1,"拿一段最小程序验证：先读数，再读整行"],["b91",-1,"这段程序先读一个整数，再读一整行，最后用方括号把读到的行括起来——空格有没有保留，一眼可见："],["b92",-1,"#include <iostream> #include <string> using namespace std; int main() { int n; string line; cin >> n; // 先读一个整数，换行留在流里 cin.ignore(); // 吃掉那个换行，否则下一行读到空串 getline(cin, line); // 再整行读入，空格一起留下 cout << n << \" [\" << line << \"]\\n\"; return 0; }"],["b94",-1,"两条边界：残留换行，以及读完别再拿 >> 去切"],["b95",-1,"getline 本身没有毛病，出问题的一定是它前面那一步："],["b96",-1,"读到的空串不是 getline 的毛病，是 cin >> 读完后残留的那个换行没被处理。加上 ignore 就恢复正常。"],["b97",-1,"getline 会把空格一起读进来，所以读完之后不要再拿 >> 去切它，要么用 stringstream，要么自己扫一遍字符。"],["b98",-1,"进入 main：声明两个 int，此刻 a、b 的值是内存里剩下的字节，不是 0"],["b99",-1,"cin >> a >> b;从左往右：先把第一个整数给 a，再把第二个给 b。中间的空格或换行由 cin 自动跳过，不需要在代码里处理"],["b100",-1,"int s = a + b;加法在寄存器里完成，结果存进 s。这一句不会产生任何输出，屏幕上什么都不会出现"],["b101",-1,"?a + b 会不会超过 2147483647？"],["b102",-1,"cout << s << \"\\n\";只写数字和一个换行。任何“答案是”这样的说明文字都会变成答案的一部分，直接 WA"],["b103",-1,"return 0：交出退出码，缓冲区在这时被整体刷出去，评测机开始逐字节比对"],["b104",-1,"样例走一遍：输入 2 3 → a = 2、b = 3 → s = 5 → 输出 5 加一个换行，共 2 个字节。"],["b105",-1,"例题 · A+B Problem · 洛谷 P1001 入门"],["b106",-1,"输入两个整数 a、b（|a|,|b| ≤ 10⁹），输出它们的和。"],["b107",-1,"题面就这么一句话，却是整门课的第一块砖：输入不过三个字符 2 3，输出只有 5，任何多余的字符都会被逐字节比对当场抓出来。"],["b108",-1,"样例"],["b109",-1,"输入： 2 3 输出： 5"],["b110",-1,"程序要接住两个数，先得有两个能装 32 位整数的位置："],["b111",-1,"int a, b; // ① 两个 32 位整数，此刻值不确定"],["b112",-1,"cin >> a >> b; // ② 按顺序把两个整数取进来"],["b113",-1,"int s = a + b; // ③ 相加，结果先存着"],["b114",-1,"cout << s << \"\\n\"; // ④ 只写数字和换行"],["b115",-1,"四步拼起来，再加上头文件、命名空间、main 和返回值，就是能直接提交的完整程序："],["b116",-1,"#include <iostream> using namespace std; int main() { int a, b; // ① 两个 32 位整数，此刻值不确定 cin >> a >> b; // ② 按顺序把两个整数取进来 int s = a + b; // ③ 相加，结果先存着 cout << s << \"\\n\"; // ④ 只写数字和换行 return 0; // ⑤ 正常结束 }"],["b117",-1,"#include <iostream> 引入标准输入输出库，cin 与 cout 的声明都在这里，删掉这一行，编译第一行就失败；using namespace std; 把 std 里的名字拉到全局，于是能写 cin 而不是 std::cin。"],["b118",-1,"int main() 是程序入口，评测系统从这里开始跑；return 0; 是正常退出的约定，退出时输出缓冲区被整体刷出去，评测机这才开始逐字节比对。不写多数编译器会替你补，但别把这种运气当规范。"],["b119",-1,"题型特征：读一组数、输出一个结果的送分题，真正的考点从来不在算法，而在格式——读几个、按什么顺序读、输出几行、每行什么形状。凡是「样例过了还是 WA」，先怀疑这一层。"],["b120",-1,"复杂度：O(1) 时间、O(1) 空间。这道题的时间限制没有意义，WA 一定出在字节上，不会是 TLE。"],["b121",-1,"输出提示语：多写一句「请输入两个数：」，整串字节就和标准答案对不上了。"],["b122",-1,"行末多打空格：5 和 5 是两条不同的字节流，严格评测直接 WA。"],["b123",-1,"忘记换行：多数题不敏感，但逐行比对的题会把最后一行判成格式错误。"],["b124",-1,"用 int 硬扛可能超范围的和：范围一放大就溢出成负数，拿不准就用 long long。"],["b125",-1,"可扩展：同一套骨架换成「读 n 个数求和」「读一行字符串再处理」，变的只是读入与输出的形状，三段式的顺序一条都不用改。"],["b126",1,"这一节最容易犯的 4 个错"],["b127",-1,"输出提示语。写 cout << \"请输入两个数：\" 会直接 WA——评测机不读中文，它只看到一个比标准答案长很多的字节流。"],["b128",-1,"用 int 硬扛可能超范围的和。本题刚好卡在 2×10⁹，再大一点（|a|,|b| ≤ 2×10⁹ 时 a + b 能到 4×10⁹）就溢出成负数。写之前先看数据范围，拿不准就用 long long。"],["b129",-1,"忘记换行。多数题对行末换行不敏感，但有些题逐行比对，最后一行没有换行会被判格式错误。"],["b130",-1,"行末多打空格。5 和 5 是两个不同的字节流，严格评测（例如 NOIP）直接 WA。数字之间该空格就空格，行末只留换行。"],["b131",2,"自己动手复现"],["b132",-1,"合上这一页，凭记忆把上面那段 A+B 完整代码敲一遍，编译运行，输入 2 3，确认输出是 5 而不是别的东西。"],["b133",-1,"把输入换成 1000000000 1000000000，输出应该是 2000000000；再换成 -1000000000 -1000000000，输出应该是 -2000000000。两次都对了，说明你读入和输出的顺序都没写反。"],["b134",-1,"然后把 int a, b; 改成 short a, b;，然后用同一个输入再跑一次——你会看到一个和 2000000000 毫不相干的数。那就是溢出，下一节正式讲它。"],["b135",-1,"最后提交到 P1001。如果 WA，先把自己的输出和标准答案逐个数一遍字节，别急着改算法——这一题的算法只有一行。"],["b136",3,"数学补给 · 为什么 int 的上限是 2.1×10⁹"],["b137",-1,"现在主流的编译器和评测机上，int 都是 4 字节 = 32 个二进制位。计算机用补码存负数，最高位是符号位：0 表示非负，1 表示负。"],["b138",-1,"剩下 31 位用来表示大小，能区分 2³¹ = 2147483648 个不同的非负值，从 0 数到 2147483647。所以最大值 = 2³¹ − 1 = 2147483647 ≈ 2.147×10⁹，最小值 = −2³¹ = −2147483648。"],["b139",-1,"负数比正数多一个，是因为补码里 0 只有一种写法（全 0），空出来的那个编码被拿去表示最小的负数。于是正负加起来正好 2³² 个数，一个不多、一个不少，这才叫“不浪费任何一种编码”。"],["b140",-1,"心算记法。2¹⁰ = 1024 ≈ 10³，于是 2³¹ = 2 × (2¹⁰)³ ≈ 2 × 10⁹。这个近似值足够回答“这题要不要开 long long”：题目里出现的量级超过 10⁹，就别用 int 存答案；到 10¹⁸ 量级必须 long long。"],["b141",-1,"类型"],["b142",-1,"字节"],["b143",-1,"范围"],["b144",-1,"十进制位数"],["b145",-1,"short"],["b147",-1,"−32768 ~ 32767"],["b148",-1,"5 位"],["b149",-1,"int"],["b151",-1,"−2147483648 ~ 2147483647"],["b152",-1,"10 位"],["b153",-1,"unsigned int"],["b155",-1,"0 ~ 4294967295"],["b156",-1,"10 位"],["b157",-1,"long long"],["b159",-1,"−9.22×10¹⁸ ~ 9.22×10¹⁸"],["b160",-1,"19 位"],["b161",-1,"一句话结论：先看数据范围，再定变量类型。long long 的加减乘比 int 慢一点点，在竞赛的量级上几乎察觉不到，宁可多开一个字节都不该赌。真正贵的是溢出之后重新提交、重新怀疑算法的那半小时。"],["b162",4,"举一反三 · 想清楚这些再往下走"],["b163",-1,"把 cout << \"answer = \" << s; 交上去，为什么是 WA？评测机到底在比什么？想好了？点开核对思路与解析结论：WA。标准答案里只有数字和换行，answer = 这 9 个字符会被当成答案的一部分。理由：评测机把两份输出当字节流逐字节比较，它不解析语义，也不会替你删前缀或忽略空格。第一个不一致的位置就是判错的起点。常见错路：拿样例对眼睛。人看“answer = 5”觉得内容对了，机器比的是第 1 个字节 'a' 和第 1 个字节 '5'——从一开始就不一样。"],["b164",-1,"先 cin >> n，再 getline(cin, s)，为什么 s 是空串？怎么改？想好了？点开核对思路与解析结论：cin >> n 在第一个非数字字符处停下，那个换行还留在流里；getline 一进流就撞上它，于是立刻返回一个空串。理由：getline 的停止条件正是“读到换行”，读到就返回，并把这个换行从流里取走。而此刻缓冲区里的第一个字符，恰好是上一次读整数时没被消耗掉的换行。改法：两者之间加一句 cin.ignore();，默认吃掉一个字符；数据行可能带多余空格时，写成 cin.ignore(…, '\\n') 把整行残余清干净。常见错路：以为 getline 坏了，换成 cin >> s——那样带空格的句子会在第一个空格处被截断，错得更隐蔽。"],["b165",-1,"输入写成 2 3（同一行）和 2 换行 3（两行），对 cin >> a >> b 有区别吗？想好了？点开核对思路与解析结论：没有区别，两种写法都能正确得到 a = 2、b = 3。中间夹几个空行也一样。理由：提取运算符把空格、Tab、换行一视同仁地当分隔符，先跳过所有空白，再解析下一个值。所以在它眼里，“换行”和“空格”是同一个东西。常见错路：以为“按行给的数据必须按行读”，于是先 getline 再自己拆——不但麻烦，还容易栽在残留换行上。另一种错路是反过来，以为 cin 会检查格式，其实输入里多写几个空格它照样算对。"],["b166",-1,"题目说 |a|,|b| ≤ 10⁹，用 int 存 a + b 真的安全吗？边界在哪？想好了？点开核对思路与解析结论：安全。最大的和是 2×10⁹ = 2000000000，比 2147483647 还小 1.47×10⁸。理由：只有两个 10⁹ 同号相加才可能顶到上限，而 2×10⁹ 与 2.147×10⁹ 之间确实留了余量。余量很小，所以在草稿纸上写下“2×10⁹ < 2.147×10⁹”这一步不能省。常见错路：把“这题能过”当成“int 永远够用”，下一道题照抄 int 就翻车；还有一种是算 (l + r) / 2 求中点时，l、r 都接近上限，相加先溢出，后面除法再准也没用——正确写法是 l + (r - l) / 2。"],["b167",5,"自测：这 5 条都能答上来，才往下走"],["b168",-1,"不看资料，写出读两个整数、输出和的完整程序，包括 #include 和 return 0;。"],["b169",-1,"说清 cin >> 和 getline 的区别，以及什么时候必须补一句 cin.ignore()。"],["b170",-1,"说出 int 的最大值，并解释为什么数据范围到了 10¹⁸ 就必须换 long long。"],["b171",-1,"用自己的话解释：为什么输出里不能有提示语、行末不能多空格——评测机究竟在比什么。"],["b172",-1,"说出 \"\\n\" 和 endl 的差别，以及为什么循环里不用 endl。"],["b173",6,"延伸阅读 / 参考"],["b174",-1,"《算法竞赛入门经典》第 1 章：程序框架与输入输出"],["b175",-1,"洛谷 P1001、P5706 的题解区，重点看别人怎么处理输出格式，而不是怎么算"],["b176",-1,"cppreference 上 std::getline 与 std::ios_base::sync_with_stdio 的条目"],["b177",-1,"各 OJ 的“评测状态说明”：AC / WA / RE / TLE / MLE 分别对应程序出了什么问题"],["b178",7,"挑战题 · 再分肥宅水"],["b179",-1,"有 t 毫升肥宅快乐水，要平均分给 n 名同学，每名同学再发 2 个杯子。求每人能分到多少毫升，以及一共要准备多少个杯子。"],["b180",-1,"输入一行两个数 t、n（0 ≤ t ≤ 10⁴，1 ≤ n ≤ 10³），t 可能是小数，n 一定是整数。"],["b181",-1,"输出两行：第一行是每人分到的毫升数，保留 3 位小数；第二行是一个整数，表示杯子的总数。"],["b182",-1,"样例 · 先手算，再对照程序输出"],["b183",-1,"输入： 500.0 3 输出： 166.667 6"],["b184",-1,"这是两个互不相干的问题：一个是实数除法，一个是整数乘法。不要试图用一句 cout 把它们一起打出来。"],["b185",-1,"“保留 3 位小数”不是“四舍五入到 3 位有效数字”。cout 里管这两件事的是两个不同的东西，少写一个，结果就从 166.667 变成 167。"],["b186",-1,"第二行是整数乘法，别写成 2.0 * n——那样它会被上一行的格式设置带成 6.000。"],["b187",-1,"第一问：每人分到 t / n 毫升。t 用 double 读，n 用 int 读，二者相除自动按实数算。输出要 3 位小数，写法是 cout << fixed << setprecision(3) << t / n。第二问：每名同学 2 个杯子，n 名同学就是 2n 个。n ≤ 1000，2n ≤ 2000，int 绰绰有余，不需要任何技巧。两行输出，各带一个换行。第一行设好的小数格式会一直保持，但它只作用于浮点数，所以第二行仍然是一个干干净净的整数。为什么不能合成一句：两问一个是浮点、一个是整数，混在一个表达式里既改不了中途的格式，也容易把杯子数打成小数。分开写，一段话对应一行输出，读代码的人（包括三天后的你）一眼就能对上题面。"],["b188",-1,"参考代码#include <iostream> #include <iomanip> using namespace std; int main() { double t; int n; cin >> t >> n; cout << fixed << setprecision(3) << t / n << \"\\n\"; // 每人分到的毫升数 cout << 2 * n << \"\\n\"; // 杯子总数 return 0; }关键片段拆解片段作用#include <iomanip>setprecision 声明在这个头文件里。只引 iostream 会得到“未声明的标识符”，编译直接失败。double t; cin >> t;t 可能是 500.0 这种带小数点的数。用 int 读会在小数点处停下，后面所有读入跟着错位。fixed切成定点表示。不加它，setprecision(3) 数的是有效数字：500/3 会输出 167，样例当场对不上。setprecision(3)配合 fixed 表示“小数点后 3 位”。它对之后的输出一直生效，所以要在这句之后的第一次输出就用上。t / nt 是 double、n 是 int，自动转成 double 再除，得到实数除法 166.6666…；若两个都是 int，除出来的 166 会把小数位全丢掉。2 * n整数乘法，输出 6。上一行的 fix…"]]},{"f":"02.html","n":2,"no":"02","t":"循环、累加与整数溢出","title":"循环、累加与整数溢出","core":"","lv":"入门","tg":["for/while","long long","溢出","累加"],"hs":["本节出现的新语法（先看懂再用）","提交前先用三组自测","这一节最容易犯的 4 个错（附症状）","自己动手复现","数学补给 · n(n+1)/2 与「先乘后除」的危险","举一反三 · 想清楚这四件事再往下走","自测：能全部回答再进下一节","延伸阅读 / 参考","挑战题 · 阶乘之和"],"b":[["b0",0,"本节出现的新语法（先看懂再用）"],["b1",-1,"for 循环 —— 次数已知时用它，三段式把「从哪开始、什么时候停、每轮怎么变」写在同一行里"],["b2",-1,"while 循环 —— 次数未知时用它，循环体里必须有一句让条件最终变假"],["b3",-1,"累加器 —— sum += x 这一行，把每一轮的结果攒进同一个变量"],["b4",-1,"long long —— 装得下 19 位整数的类型，求和之前先估上界，再决定要不要换它"],["b5",-1,"第 1 节的程序只算一次：读一个数、算一次、输出。这一节要让程序算一千万次，但代码一行都不多加——循环的全部作用就是把「重复」这件事交给机器。拆开看只有三个问题：从哪里开始、什么时候停、每一轮做什么。想不清这三个问题，写出来的不是死循环就是差一项。"],["b6",-1,"这两件事经常被混成一件。本节例题的循环要跑一千万圈，这是「多不多」的问题；而那个和的答案有 5×10¹³ 那么大，这是「装不装得下」的问题。前者算错，程序跑到超时被判 TLE；后者算错，程序按时跑完却输出一个负数，被判 WA。两类错误的症状、排查方向、修改位置全都不同，所以从一开始就分开算。"],["b7",-1,"例题 · 数列求和 · 洛谷 P5722 入门"],["b8",-1,"给定一个正整数 n，求 1 + 2 + 3 + … + n 的值。"],["b9",-1,"输入格式：一行一个正整数 n（1 ≤ n ≤ 10⁷）。输出格式：一行一个整数，表示这个和。"],["b10",-1,"本题的 n 只到一千万，所以「一项一项加」完全跑得动，就用循环写；等差数列公式 n(n+1)/2 放在本节末尾的数学补给里，用它来验算和估范围，不用它来替代循环。"],["b11",-1,"样例"],["b12",-1,"输入： 100 输出： 5050"],["b13",-1,"long long n; cin >> n; // 1 <= n <= 1e7"],["b14",-1,"n 最大 10⁷，int 装得下。这里仍写 long long，是为了让 i <= n 两边的类型一致，不出现隐式转换这种需要额外解释的东西。"],["b15",-1,"读入一行一个整数，换行符会被自动跳过，不用额外处理。"],["b16",-1,"long long sum = 0; // 累加器：初值必须自己写 0"],["b17",-1,"for (long long i = 1; i <= n; ++i) { // 初始化 / 判断 / 每轮末尾 ++i sum += i; // 循环体：把第 i 项加进去 }"],["b18",-1,"从 1 起步、到 n 为止、每轮加 1。<= 决定 n 也在里面，一共 n 轮；写成 < 就只有 n−1 轮，最后一项被关在循环外面。"],["b19",-1,"sum += i; 是循环体唯一一句，被执行 n 次，等价于手写 n 行加法。循环结束后 i 就失效了，花括号后面不要再拿 i 当第 n 项用。"],["b20",-1,"cout << sum << \"\\n\"; // n 项都加完了，输出"],["b21",-1,"五段拼起来，再加上万能头文件和 return 0;，就是能直接提交的一份程序："],["b22",-1,"#include <bits/stdc++.h> using namespace std; int main() { long long n; cin >> n; // 1 <= n <= 1e7 long long sum = 0; // 累加器：初值必须自己写 0 for (long long i = 1; i <= n; ++i) { // 初始化 / 判断 / 每轮末尾 ++i sum += i; // 循环体：把第 i 项加进去 } cout << sum << \"\\n\"; // n 项都加完了，输出 return 0; }"],["b23",-1,"#include <bits/stdc++.h> 是万能头，一次顶掉 iostream、climits 这些零碎头文件，竞赛里几乎每份代码都用它。"],["b24",-1,"return 0; 告诉评测机程序正常结束：退出时输出缓冲区被整体刷出去，评测机这才开始逐字节比对答案。"],["b25",-1,"题型特征：看到「求 1 到 n 的和」「把 n 个数加起来」「数一数有多少个满足条件」，先想「累加器 + 单层循环」这个骨架。它的标志是每一轮做的事完全一样，只是下标在变。"],["b26",-1,"复杂度：O(n) 时间、O(1) 空间。n = 10⁷ 时约 10⁷ 次加法，十几毫秒；n 一旦涨到 10⁹，同样的代码要跑好几秒，那时必须换公式或者换算法，而不是把循环写得更紧。"],["b27",-1,"累加器不初始化：结果是栈上的随机值，样例小的时候还可能碰巧对上。"],["b28",-1,"边界差一次：i < n 只有 n−1 轮，n = 1 时直接输出 0。"],["b29",-1,"用 int 求和：加到 65536 就翻成负数，样例（n = 100）完全正常。"],["b30",-1,"乘法先溢出再赋值：long long ans = a * b; 先按 32 位乘完，残值才转成 64 位。"],["b31",-1,"可扩展：求积把初值换成 1；求最大值时初值不能随手写 0（数据可能全是负数），要写成 −INF 或者第一个元素。"],["b32",-1,"题面读完了，先别写代码。下面三张卡分别讲「怎么重复」「什么时候停」「用什么类型装」，每张都配一段能直接编译运行的示例；看完再回到这道题，代码只是把这些零件拼起来。"],["b34",-1,"需求 → 把三件事塞进同一行：初始化、条件、步进"],["b35",-1,"既然三个问题必须一起回答，那就在同一行里回答。for 的括号里用两个分号切成三段，正好对上三个问题："],["b36",-1,"for (初始化; 条件; 步进) { 循环体 }"],["b37",-1,"括号里的三段只管「转几圈」，花括号里的循环体才是「每圈做什么」。两件事分开写，改轮数不会动到循环体。"],["b39",-1,"拆开看：三段各在什么时候执行"],["b40",-1,"这一行之所以能表达「重复」，靠的是三段各自的执行时机——初始化只做一次，条件每圈问一次，步进每圈末尾做一次："],["b41",-1,"组成"],["b42",-1,"含义 / 格式要求"],["b43",-1,"初始化"],["b44",-1,"进循环之前只执行一次，通常写 int i = 1。循环变量在这里诞生，也只在这层循环里有效。"],["b45",-1,"条件"],["b46",-1,"每一轮开始前检查一次，为真才进循环体。i <= n 配从 1 起步，正好是 n 轮。"],["b47",-1,"步进"],["b48",-1,"每轮循环体结束后执行。++i 与 i++ 写在这里等价，换成 i += 2 就变成隔一个取一个。"],["b49",-1,"两个分号"],["b50",-1,"三段之间用分号隔开，不是逗号，一个都不能省。"],["b51",-1,"循环体"],["b52",-1,"只有一句也写花括号，以后往里加第二句时不会漏掉边界。"],["b54",-1,"拿一段最小程序验证：累加 100 项、再从 0 数到 4"],["b55",-1,"这段程序跑两个循环：第一个验证「从 1 加到 100」，第二个验证「从 0 起步要写 i < 5」："],["b56",-1,"#include <bits/stdc++.h> using namespace std; int main() { long long sum = 0; for (int i = 1; i <= 100; ++i) sum += i; // 循环体：加进去，然后回到条件 cout << sum << \"\\n\"; // 5050 for (int i = 0; i < 5; ++i) cout << i << \" \"; // 0 1 2 3 4，从 0 起步就写 i < 5 cout << \"\\n\"; return 0; }"],["b57",-1,"两次输出分别是 5050 和 0 1 2 3 4。数一下第二行有几个数，就知道 i < 5 为什么是 5 轮。"],["b59",-1,"两条边界：差一项、以及步进和条件对着干"],["b60",-1,"for 的 bug 几乎都能归到「轮数不对」这一类，而轮数只由条件和步进决定："],["b61",-1,"条件里的边界符号直接决定轮数：i <= n 是 n 轮，i < n 只有 n−1 轮。写完先拿 n = 1 试一次——正确答案是 1，程序输出 0 就说明少了一轮。"],["b62",-1,"步进别和条件对着干：i <= n 配 i += 2 而 n 是奇数时，i 会从 n−1 直接跳到 n+1，这一轮白漏；把条件写成 i != n 再配 i += 2，就是永远退不出。"],["b64",-1,"需求 → 只写「停的条件」，不写轮数"],["b65",-1,"把 for 的三段砍成一段：既然不知道轮数，就只保留「每圈开始前问一次」的那个条件，其余交给循环体自己推进："],["b66",-1,"while (条件) { 循环体 }"],["b67",-1,"没有初始化段、也没有步进段。这两件事不是消失了，而是被挪进了循环体——所以写 while 时，脑子里必须一直记着「谁负责让它停下来」。"],["b69",-1,"拆开看：五个关键词各管什么"],["b70",-1,"组成"],["b71",-1,"含义 / 格式要求"],["b72",-1,"while"],["b73",-1,"每一轮开始前检查条件，为真就再转一圈。没有初始化段和步进段，全靠自己写。"],["b74",-1,"何时用"],["b75",-1,"次数未知时用它：不知道要转几圈，只知道转到什么状态就该停。"],["b76",-1,"让它变假"],["b77",-1,"循环体里必须有一句改变条件里的量，否则条件永远为真，程序卡死 → TLE。"],["b78",-1,"break"],["b79",-1,"立刻跳出整个循环，适合「找到就停」。循环末尾的语句一句都不再执行。"],["b80",-1,"continue"],["b81",-1,"跳过本轮剩下的语句直接进下一轮判断。for 里它会先做步进，别和 while 混着理解。"],["b83",-1,"拿一段最小程序验证：27 要多少步才掉到 1"],["b84",-1,"这段程序把 while 的「条件 + 推进」写全了：条件是 n != 1，推进是循环体里那两支："],["b85",-1,"#include <bits/stdc++.h> using namespace std; int main() { long long n; cin >> n; // 输入 27 int step = 0; // 计数器：每轮只加 1 的累加器 while (n != 1) { // 停的条件是 1，不是 0 if (n % 2 == 0) n /= 2; // 偶数折半 else n = 3 * n + 1; // 奇数变 3n+1 ++step; // 走哪一支都要记一步 } cout << step << \"\\n\"; // 输出 111 return 0; }"],["b86",-1,"跑出来是 111：从 27 出发，111 步之后才第一次等于 1。这个数事先谁也算不出来，正是「轮数未知」的典型。"],["b88",-1,"两条边界：谁让条件变假、条件写错一位"],["b89",-1,"while 的 bug 只有一类：条件永远为真。写之前先指着循环体回答一句「哪一行会让它变假」："],["b90",-1,"写 while 之前先回答一句话：循环体里哪一行会让条件变假？答不出来就会写出死循环。上面这段里变的是 n，而 n /= 2 与 n = 3 * n + 1 两支都在缩小或推进这个数。"],["b91",-1,"条件写错一位就换个故事：写成 n > 0 的话 n 永远为正，程序一直转到溢出为止。反过来写成 n != 0 又会在 n 恰好跳到 0 时停住——而这道题的出口是 1。"],["b93",-1,"需求 → 先看两个候选类型的容量"],["b94",-1,"能装整数的类型不止一个，它们的区别只在「几位」。把这行当成签名读：左边是类型，右边是它能装到的上限："],["b95",-1,"int // 32 位，上限 2147483647 long long // 64 位，上限 9223372036854775807"],["b96",-1,"选类型不是看「数有多大」，而是看「算出来的量最大能有多大」——本题的答案是 n(n+1)/2，不是 n。"],["b98",-1,"拆开看：范围、怎么估、什么时候换"],["b99",-1,"组成"],["b100",-1,"含义 / 格式要求"],["b101",-1,"int 的范围"],["b102",-1,"−2147483648 到 2147483647，约 ±2.1×10⁹，十位数。超出去不会报错，只会把高位丢掉、绕回负数。"],["b103",-1,"long long 的范围"],["b104",-1,"约 ±9.22×10¹⁸，十九位数。日常题目里「装得下 10¹⁸」就够了。"],["b105",-1,"怎么估"],["b106",-1,"一个乘法：项数 × 单项最大值。1..n 的项数是 n、单项最大是 n，所以上界约 n²/2。"],["b107",-1,"什么时候换"],["b108",-1,"上界超过 2.1×10⁹ 就用 long long。拿不准时先换——多占 4 个字节，不会更慢。"],["b109",-1,"乘法陷阱"],["b110",-1,"a * b 的类型由 a、b 决定，和左边接收它的变量无关；要写 1LL * a * b 把整个式子抬到 64 位。"],["b112",-1,"拿一段最小程序验证：同一个循环，两种累加器"],["b113",-1,"这段程序用同一个 n = 65536 跑两遍，只换累加器的类型："],["b114",-1,"#include <bits/stdc++.h> using namespace std; int main() { int n = 65536; int bad = 0; // 32 位累加器 for (int i = 1; i <= n; ++i) bad += i; cout << bad << \"\\n\"; // -2147450880，溢出后的残值 long long good = 0; // 64 位累加器，同一个循环 for (int i = 1; i <= n; ++i) good += i; cout << good << \"\\n\"; // 2147516416 int a = 100000, b = 100000; cout << a * b << \"\\n\"; // 1410065408，先按 32 位乘完 cout << 1LL * a * b << \"\\n\"; // 10000000000，1LL 把式子抬到 64 位 return 0; }"],["b115",-1,"第一行是 -2147450880，第二行是 2147516416。同一个循环、同一个 n，差别只在声明那一行——而编译器一句警告都没有。"],["b117",-1,"两条边界：溢出是静默的、看中间量不看结果"],["b118",-1,"溢出最麻烦的地方不是结果错，而是它错得毫无提示："],["b119",-1,"溢出是「静默」的：编译器不警告、程序不崩溃、样例照样对，只有大数据会输出一个荒唐的数字。所以类型选择不能靠运行结果来试，必须在写代码前用乘法估一遍。"],["b120",-1,"估的时候别只看答案：long long ans = a * b 里答案本身是 10¹⁰，long long 完全装得下，但乘法那一步是在 32 位里做的。看中间量，不看结果。"],["b121",-1,"三张卡拼起来，就是例题的全部零件：for 让 i 从 1 走到 n，sum += i 把这 n 项收进同一个变量，long long 保证这个变量装得下 5×10¹³。下一张图把它们连成一条执行路线。"],["b122",-1,"准备：读入 n，累加器 sum = 0，循环变量 i = 1（第 5 ~ 8 行）"],["b123",-1,"?i <= n ？（第 9 行，每圈开头问一次）"],["b124",-1,"sum += i;第 10 行：累加器只在这一行变化；转 n 圈就加 n 次，一次不多一次不少"],["b125",-1,"++i;第 9 行末尾的步进：每圈把 i 推大 1，条件因此迟早会变假"],["b126",-1,"回到判断：拿新的 i 再问一次 i <= n，是就再转一圈"],["b127",-1,"输出：cout << sum（第 13 行），此刻 sum 已经是全部 n 项之和"],["b128",-1,"判断方框在圈的开头，这一点值得多看两眼：i 先被问一次「你还在 1..n 里面吗」，通过了才把 i 加进 sum。所以 i = n 的那一圈确实被加进去了，答案才是 n 项而不是 n−1 项——循环题里绝大部分的差一错误，都能在这张图上找到位置。"],["b129",1,"提交前先用三组自测"],["b130",-1,"n = 1 → 1；n = 100 → 5050；n = 10⁷ → 50000005000000。"],["b131",-1,"第三组能过，说明 long long 选对了；如果输出的是 -2004260032 这种负数，说明 64 位没落实——多半是 sum 还写着 int。"],["b132",2,"这一节最容易犯的 4 个错（附症状）"],["b133",-1,"WA · 累加器不初始化。写成 long long sum; 然后直接 sum += i，局部变量的初值是栈上残留的旧数据，同一份代码跑两次结果都可能不同；样例小的时候容易碰巧对上，一交大数据就挂。"],["b134",-1,"WA · 边界差一次。i < n 只有 n−1 轮，最后一项被关在循环外面；i <= n 写成 i <= n + 1 则多算一项。拿 n = 1 试一次，正确答案是 1，输出 0 就是少了一轮。"],["b135",-1,"WA · 用 int 求和。int sum = 0 一路加到 65536 得到 -2147450880，一个负数。它不报错、不崩溃、样例照样过（n = 100 的和才 5050），只有大数据露馅，是最难靠样例发现的一类。"],["b136",-1,"WA · 乘法先溢出再赋值。long long ans = a * b; 里 a、b 都是 int，乘法先按 32 位算完，残值再存进 64 位变量；(long long)(a * b) 错得一模一样。只有 1LL * a * b 或者把 a 本身声明成 long long 才对。"],["b137",3,"自己动手复现"],["b138",-1,"关掉页面，从空文件把例题敲一遍，用 n = 1、100、10⁷ 三组自测，再提交。敲的过程中刻意念一遍：初始化在哪、判断在哪、循环体在哪、输出在循环外面。"],["b139",-1,"改一改：把 long long sum = 0; 换成 int sum = 0;，先输入 65535 得到 2147450880（对的），再输入 65536 得到 -2147450880（错的）。两个数只差 1，结果一正一负，把这两次输出记下来，以后估范围时会想起它。"],["b140",-1,"再改一改：把条件改成 i < n，输入 100，输出从 5050 变成 4950；然后把起点改成 0、条件写回 i <= n，输入 100 还是 5050——多转的那一圈加的是 0，加法里感觉不到。同一个「差一」，为什么一处出错、一处没错？想明白这一点，循环边界就真的过关了。"],["b141",-1,"最后改一改：把 sum += i 挪到循环后面去（挪出花括号），看输入 100 时输出几，再解释为什么不是 5050。"],["b142",4,"数学补给 · n(n+1)/2 与「先乘后除」的危险"],["b143",-1,"把 1 到 n 正着写一遍，再倒着写一遍，上下对齐：第一列 1 与 n、第二列 2 与 n−1、最后一列 n 与 1，每一列的和都是 n+1，一共 n 列。所以 2S = n(n+1)，S = n(n+1)/2。高斯当年的做法，也是本类题最好的验算工具。"],["b144",-1,"公式最大的价值是「写代码之前就能算」。拿它代一下最坏情况：n = 10⁷ 时 S = 5.0000005×10¹³，比 int 的上限 2147483647 大两万倍，所以累加器必须是 64 位。这一步只花十秒，却能省掉一次 WA 和半小时的排查。"],["b145",-1,"它还能精确算出 int 哪天不够用。解 n(n+1)/2 > 2147483647，得 n ≥ 65536：65535 的和是 2147450880，离上限只差 32767；65536 的和是 2147516416，刚好越线，回绕成 -2147450880。本节反复出现的这两个数，就是从这里来的。"],["b147",-1,"1+2+…+n"],["b148",-1,"用什么类型装"],["b149",-1,"100"],["b150",-1,"5050"],["b151",-1,"int 就够，样例级数据"],["b152",-1,"65535"],["b153",-1,"2147450880"],["b154",-1,"int 能装的最后一格"],["b155",-1,"65536"],["b156",-1,"2147516416"],["b157",-1,"必须 long long"],["b158",-1,"10⁷"],["b159",-1,"50000005000000"],["b160",-1,"long long，本节例题的答案"],["b161",-1,"10⁹"],["b162",-1,"500000000500000000"],["b163",-1,"long long，且 n 本身也要 64 位"],["b164",-1,"公式自己也会溢出，而且危险在中间：n(n+1) 比最终结果大一倍，先乘后除的顺序改不掉。n = 10⁹ 时中间量约 10¹⁸，n 如果还是 int，乘的那一瞬间就已经错了；n 是 long long 时安全区一直到 n ≈ 3.03×10⁹（此时 n(n+1) ≈ 9.2×10¹⁸，逼近 2⁶³−1），再往上连 long long 都装不下中间量，只能先除后乘、或者换更宽的表示。"],["b165",-1,"所以「用公式」不等于「不会溢出」。换公式只是把循环次数从十亿降到零，类型仍然要按中间量重新估一遍——这两件事在竞赛里从来是分开算的。"],["b166",5,"举一反三 · 想清楚这四件事再往下走"],["b167",-1,"把例题的条件从 i <= n 改成 i < n，n = 100 时输出多少？和正确答案差多少？为什么拿 n = 1 一试就能发现？想好了？点开核对思路与解析输出 4950，比正确答案少 100，差的正好是被关在循环外面的最后一项。理由：i 只走到 99，循环跑 99 轮，第 100 项从来没有被加进去。拿 n = 1 试最快：正确输出 1，改过的版本一轮都不进、sum 停在 0，一眼看出问题。常见错路是只看样例（n = 100）就下结论——4950 这个数看起来同样「像答案」，没有对照根本发现不了。"],["b168",-1,"把累加器写成 int sum，n 从 1 开始慢慢增大，第一个开始出错的 n 是多少？出错时程序会崩溃吗？想好了？点开核对思路与解析第一个出错的是 n = 65536。65535 的和是 2147450880，还小于 2147483647；65536 的和是 2147516416，超了 32769，于是绕回负数 -2147450880。不会崩溃，也不会报错：高位被丢掉，低位照常显示，程序安静地输出一个负数。这就是溢出最危险的地方——它不给你任何提示。常见错路：①以为 int 上限是「21 亿个数」所以 n 到 10⁹ 才出事，其实 n = 10⁵ 时和已经 5×10⁹；②以为溢出会让程序段错误，于是去查数组越界。"],["b169",-1,"a、b 都是 int，各等于 100000。long long ans = a * b; 为什么错？1LL * a * b、(long long)a * b、(long long)(a * b) 三种改法哪些对？想好了？点开核对思路与解析结论：第一种写法输出 1410065408，第二种写法输出 10000000000。理由：表达式的类型在「计算的那一刻」由操作数决定，和左边拿什么变量接收毫无关系。a * b 两边都是 int，就先按 32 位乘出一个残值，再把这个残值转成 64 位存起来。三种改法里，1LL * a * b 和 (long long)a * b 都对：乘法从左往右算，第一个乘数变成 64 位后，整条式子就都是 64 位了。(long long)(a * b) 错，括号里的乘法早就按 32 位算完了，转换只是把残值搬个地方。常见错路：用 double 中转。10¹⁰ 时它碰巧还准，数据一到 10¹⁸ 就开始丢末尾几位。"],["b170",-1,"本题 n ≤ 10⁷ 用循环没问题。如果 n 的上限改成 10⁹，循环还能用吗？换成公式之后，最危险的一步在哪？想好了？点开核对思路与解析结论：10⁹ 次循环在评测机上要好几秒，稳 TLE，必须换公式；换公式后最危险的一步是 n * (n + 1) 这个乘法，n = 10⁹ 时中间量约 10¹⁸，n 若是 int 就先在 32 位里溢出了。理由：中间量比最终结果大一倍，而「先乘后除」的顺序没得选——先把 n 除 2 只在 n 是偶数时成立，奇数时会丢半个 n。正确写法：n 声明成 long long（或者写 1LL * n * (n + 1) / 2），让乘法一开始就在 64 位里做。常见错路：①(long long)(n * (n + 1)) / 2，括号里已经溢出了；②n / 2 * (n + 1) 以为先除能避险，n 是奇数时答案少一半。"],["b171",6,"自测：能全部回答再进下一节"],["b172",-1,"能不看资料写出 for 的三段式，并说清「次数已知用 for、次数未知用 while」的判断依据。"],["b173",-1,"能说出三种初值：求和 0、求积 1、求最大值不能随手写 0，以及不初始化时会出现什么症状。"],["b174",-1,"拿到一道求和题，先用「项数 × 单项最大值」估一遍上界，再决定 int 还是 long long。"],["b175",-1,"能解释 65536 这个数字：为什么 1+2+…+65535 装得进 int，再多一项就装不下。"],["b176",-1,"能说清 long long ans = a * b 与 1LL * a * b 的区别，并说明为什么 (long long)(a * b) 也是错的。"],["b177",7,"延伸阅读 / 参考"],["b178",-1,"《算法竞赛入门经典》第 2 章：循环结构与累加模式，里面有大量「先估范围再选类型」的例题。"],["b179",-1,"cppreference 的「Implicit conversions」条目：整型提升与常见算术转换的完整规则，读完能解释为什么 int 与 long long 混算会得到 64 位结果。"],["b180",-1,"洛谷 P5722、P5726、P1009 题解区的高赞思路：从一维累加一路走到阶乘求和与高精度。"],["b181",-1,"C++ Core Guidelines 里关于有符号整数溢出的条款：它属于未定义行为，标准并没有规定必须绕回负数。"],["b182",8,"挑战题 · 阶乘之和"],["b183",-1,"给定一个正整数 n，求 1! + 2! + … + n! 的值。例如 n = 3 时，答案是 1 + 2 + 6 = 9。"],["b184",-1,"输入格式：一行一个整数 n（1 ≤ n ≤ 20）。输出格式：一行一个整数，表示这个和。"],["b185",-1,"数据范围刻意只到 20：20! = 2432902008176640000，连同前面的项加起来是 2561327494111820313，还在 long long 的上限 9.22×10¹⁸ 之内；n = 21 时只这一项就有 5.1×10¹⁹，立刻越界。"],["b186",-1,"样例"],["b187",-1,"输入： 3 输出： 9"],["b188",-1,"每一轮都要从 1 重新乘到 i 去算 i! 吗？上一轮算出来的乘积，离 i! 只差一个因子。"],["b189",-1,"需要两个变量：一个滚动的阶乘（初值 1），一个收集答案的和（初值 0）。注意两句的先后。"],["b190",-1,"答案有 19 位，两个变量都得能装下 19 位的数。int 在 n = 13 那一轮就已经翻了。"],["b191",-1,"先手算 n = 1、2、3：答案分别是 1、3、9。程序对上了再提交。"],["b192",-1,"先看暴力：外层枚举 i，内层从 1 乘到 i 得到 i!，再累加。n = 20 时是 20 轮、每轮最多 20 次乘法，一共 400 次运算，能过，但其中 19 轮的工作是重复的。改成递推：i! = (i−1)! × i。一个变量 fact 从头滚到尾，每轮只乘一次，总运算量降到 20 次乘法，这就是把「重算」换成「接着算」。顺序是关键：必须先把 fact 更新成 i!，再加进 sum。反过来的话，sum 里加的是 (i−1)!，n = 3 时输出 3 而不是 9，而且样例小的时候特别容易蒙对别的东西。边界：n = 1 时循环正好跑一轮，fact = 1、sum = 1；fact 的初值写 0 会让每一项都变成 0，写 2 会让 1! 那项变成 2。数值：Σk=1..20 k! = 2561327494111820313，19 位，long long 上限 9223372036854775807 装得下。这也是题目把 n 卡在 20 的原因——再大就必须上高精度了。复杂度：O(n) 时间、O(1) 空间，n = 20 时 20 次乘法加 20 次加法。"],["b193",-1,"参考代码#include <bits/stdc++.h> using namespace std; int main() { int n; cin >> n; // 1 <= n <= 20 long long fact = 1; // 求积的初值必须是 1 long long sum = 0; // 求和的初值是 0 for (int i = 1; i <= n; ++i) { fact *= i; // (i-1)! 乘上 i 就是 i!，只乘一次 sum += fact; // 把第 i 项加进答案 } cout << sum << \"\\n\"; return 0; }关键片段拆解片段作用long long fact = 1;滚动阶乘。初值 1 是乘法的单位元，第一次 fact *= 1 不改变结果；写 0 则所有项恒为 0。long long sum = 0;求和累加器。和 fact 一样必须 64 位，13! 就已经超过 int 上限。fact *= i;把上一轮的 (i−1)! 变成 i!。这一句让内层循环彻底消失，总复杂度从 O(n²) 降到 O(n)。sum += fact;先乘后加。两句一换顺序，sum 里加的就成了 (i−1)!，n = 1 时直接输出 0。for (int i = 1; i <= n; ++i)n ≤ 20，最多 20 轮，一轮不多一轮不少。co…"]]},{"f":"03.html","n":3,"no":"03","t":"前缀和与差分","title":"前缀和与差分","core":"","lv":"普及-","tg":["前缀和","差分","区间修改","二维前缀和"],"hs":["本节出现的新写法（先看懂再用）","四个最容易踩的坑（都写清症状）","自己动手复现（合上这一页再写）","数学补给 · 一次减法为什么能代替一次循环","举一反三 · 想清楚这些再往下走","过关自测（全部做到再往下）","延伸阅读 / 参考","挑战题 · 语文成绩","挑战 2 · 难度高一级，要把二维前缀和与边界一起想清楚","挑战 2 · 激光炸弹"],"b":[["b0",0,"本节出现的新写法（先看懂再用）"],["b1",-1,"pre 数组（一维前缀和） —— 一次 O(n) 建表，换每次区间和 O(1)"],["b2",-1,"d 数组（一维差分） —— 一次区间加压成两次单点加，最后统一还原"],["b3",-1,"二维前缀和（容斥） —— 矩形和 = 四个前缀和，两加两减"],["b4",-1,"1 基下标 + 哨兵 0 —— 让 l = 1、x = 1 这类边界不用特判"],["b5",-1,"数组题里有两类问题，表面看几乎一样，解法却正好相反。"],["b6",-1,"查得多、改得少：给 n 个数，q 次询问「第 l 个到第 r 个加起来是多少」。"],["b7",-1,"改得多、问得少：给 n 个数，q 次操作「第 l 个到第 r 个每个加 v」，最后一次性输出。"],["b8",-1,"两题的朴素做法都是 for 一遍区间，单次 O(len)。当 n 和 q 都到 10⁵ 时，最坏要做 10¹⁰ 次加法，按每秒 10⁸ 次估算得跑一百秒，必然 TLE。前缀和与差分，就是把「区间长度」这个因子从复杂度里消掉的两个手段。"],["b9",-1,"它们的共同点只有一句话：把一段区间换成一个（或两个）端点上的值。前缀和把「区间和」换成「两个前缀相减」，差分把「一次区间修改」换成「两次单点修改」。两者互为逆运算：对差分数组做一遍前缀和就回到原数组，对前缀和数组做一遍差分也回到原数组。记住这一条，二维的公式不用死背，可以自己推出来。"],["b10",-1,"先把要用的两个数组定义清楚：它们存的东西，和原数组完全不是一回事。pre 存的是「累计量」，d 存的是「变化量」。"],["b12",-1,"需求 → 先造一个只看下标、不看询问的数组"],["b13",-1,"观察一下：第 i 个询问要的是 a[l..r] 的和，而「a 的前 r 个数的和」与「a 的前 l-1 个数的和」都只跟下标有关，和具体是哪一次询问无关。于是把「前 i 个数的和」全部预先存下来："],["b14",-1,"pre[0] = 0; // 哨兵：前 0 个数的和 pre[i] = pre[i-1] + a[i]; // i = 1..n，只能从小到大 sum(l, r) = pre[r] - pre[l-1];"],["b15",-1,"第一行是哨兵，第二行是建表（O(n) 扫一遍），第三行是查询。三行加起来就是前缀和的全部代码。"],["b17",-1,"拆开看：哨兵、递推、查询各解决什么"],["b18",-1,"组成"],["b19",-1,"含义 / 格式要求"],["b20",-1,"pre[i]"],["b21",-1,"前 i 个数的和，即 a[1] + a[2] + … + a[i]。它存的是累计量，不是第 i 个数。"],["b22",-1,"pre[0] = 0"],["b23",-1,"哨兵，含义是「前 0 个数的和」。有了它，l = 1 时 pre[l-1] 仍然是一个有定义的值，不必给 l = 1 单独写 if。"],["b24",-1,"pre[i] = pre[i-1] + a[i]"],["b25",-1,"递推式：这一格 = 左边一格 + 本格的 a[i]。i 必须从小到大，因为 pre[i] 依赖 pre[i-1]。"],["b26",-1,"pre[r] - pre[l-1]"],["b27",-1,"查询公式。减法把 a[1..l-1] 削掉，剩下的正好是 a[l..r]；l = r 时退化成 a[l]。"],["b28",-1,"1 基下标"],["b29",-1,"数据放 a[1..n]，答案放 pre[0..n]。两个数组的下标体系必须对齐，混用 0 基会让整道题偏移一位。"],["b30",-1,"元素类型"],["b31",-1,"pre 的类型按「和」的量级选，不按 a 的类型选。n = 10⁵、aᵢ = 10⁴ 时和是 10⁹，已经贴着 int 上限，一律用 long long。"],["b33",-1,"拿一段最小程序验证：建一次表，问一次区间"],["b34",-1,"这段程序用 a = 3 1 4 1 5 建表，再问一次 [2,5]："],["b35",-1,"#include <bits/stdc++.h> using namespace std; int main() { int n = 5; long long a[6] = {0, 3, 1, 4, 1, 5}; // a[0] 空着不用，数据放 1..5 long long pre[6]; pre[0] = 0; // 哨兵：前 0 个数的和 for (int i = 1; i <= n; ++i) pre[i] = pre[i - 1] + a[i]; // O(n) 建表 // 区间 [2,5] 的和：pre[5] - pre[1] cout << pre[5] - pre[1] << \"\\n\"; // 14 - 3 = 11 return 0; }"],["b36",-1,"手算 pre = 0 3 4 8 9 14，查询 pre[5] - pre[1] = 14 - 3 = 11，与逐项相加 1 + 4 + 1 + 5 = 11 一致。"],["b38",-1,"两条边界：pre 是一条链、两套下标必须对齐"],["b39",-1,"pre 是一条链：每一格都由左边一格推出来，所以某一格错了，它右边的格子会跟着错。调试时先把整张 pre 打印出来，与手算的前几项对齐。"],["b40",-1,"建表和查询必须用同一套下标。数据放 0..n-1、公式写 pre[r] - pre[l-1]，是最常见的一位偏移。"],["b42",-1,"需求 → 不记「值」，改记「相邻两项差了多少」"],["b43",-1,"既然区间加是「一整段同时 +v」，那就别再存每个位置的值，改存「从上一格到这一格变了多少」。这样一次区间加，只会在区间的头和尾留下两处痕迹："],["b44",-1,"d[i] = a[i] - a[i-1]; // i = 1..n，a[0] 视为 0 d[l] += v; d[r+1] -= v; // 一次区间加 = 两次单点加 cur += d[i]; // 还原：对 d 做前缀和"],["b45",-1,"第一行建差分，第二行做一次区间加，第三行把记录还原成真实值。三行就是差分的全部。"],["b47",-1,"拆开看：为什么「两个单点」等于「一整段」"],["b48",-1,"组成"],["b49",-1,"含义 / 格式要求"],["b50",-1,"d[i]"],["b51",-1,"相邻两项之差，记录「a 从上一格到这一格变了多少」。它是一张改动记录，不是原数组。"],["b52",-1,"d[l] += v"],["b53",-1,"从 l 开始，每个位置都「多出一层 v」。还原时这层 v 会一直累加下去。"],["b54",-1,"d[r+1] -= v"],["b55",-1,"在 r 的下一格把这层 v 撤掉。两句合起来，影响范围恰好是 [l, r]。"],["b56",-1,"cur += d[i]"],["b57",-1,"还原式，等价于对 d 做一遍前缀和。这一步必须做，不做就输出 d，答案完全不对。"],["b58",-1,"数组大小"],["b59",-1,"要写 d[r+1]，而 r 可以等于 n，所以 d 至少开 n+2 个位置。只开 n 个一定越界。"],["b60",-1,"适用场景"],["b61",-1,"先集中修改、最后统一输出。要「改一次马上问一次」，差分帮不上忙，需要树状数组。"],["b63",-1,"拿一段最小程序验证：[2,4] 每个数加 10"],["b64",-1,"拿 a = 3 1 4 1 5 走一遍：建差分，做一次区间加，再还原并打印："],["b65",-1,"#include <bits/stdc++.h> using namespace std; int main() { int n = 5; long long a[6] = {0, 3, 1, 4, 1, 5}; long long d[7] = {0}; // 比 n 多开一位：要写 d[n+1] for (int i = 1; i <= n; ++i) d[i] = a[i] - a[i - 1]; // 建差分 d[2] += 10; // [2,4] 每个数加 10 d[5] -= 10; // 从 5 开始撤掉这层 10 long long cur = 0; for (int i = 1; i <= n; ++i) { cur += d[i]; // 前缀和还原 cout << cur << \" \"; } cout << \"\\n\"; // 3 11 14 11 5 return 0; }"],["b66",-1,"输出 3 11 14 11 5：第 2、3、4 个数各加了 10，第 1、5 个没动。两次单点修改，替换了一次长度为 3 的循环。"],["b68",-1,"两条边界：d 不是答案、d[r+1] 会写到 n+1"],["b69",-1,"d 不是答案，它只是一串「待结算的改动」。输出前必须补做一遍前缀和，把记录翻译回真实值；不翻译就直接打印，结果会差得离谱。"],["b70",-1,"写出 d[r+1] 时编译器不会拦你：它改的可能是紧挨着的另一个变量，最后表现为「某一小段数据莫名其妙不对」，这类 bug 最难定位。"],["b72",-1,"需求 → 定义「左上角到 (i,j) 的整块和」"],["b73",-1,"一维里 pre[i] 是「前 i 个数」。二维照抄这个定义：pre[i][j] 是左上角 (1,1) 到 (i,j) 这一整块的和。于是建表要一整块一整块地推，查询则从这个定义出发反解："],["b74",-1,"pre[i][j] = pre[i-1][j] + pre[i][j-1] - pre[i-1][j-1] + a[i][j]; // 建表 sum(x1,y1,x2,y2) = pre[x2][y2] - pre[x1-1][y2] - pre[x2][y1-1] + pre[x1-1][y1-1];"],["b75",-1,"建表一行、查询一行，符号都是四个，只是顺序不同——这正是容斥的两副面孔。"],["b77",-1,"拆开看：四个符号分别在加什么、减什么"],["b78",-1,"组成"],["b79",-1,"含义 / 格式要求"],["b80",-1,"pre[i][j]"],["b81",-1,"左上角 (1,1)、右下角 (i,j) 这个矩形里所有数之和。它是一整块，不是一行。"],["b82",-1,"建表 + + − +"],["b83",-1,"上面一块 + 左边一块 − 左上角重叠的那一块 + 本格。重叠块被加了两次，所以要减一次。"],["b84",-1,"查询 + − − +"],["b85",-1,"大矩形 − 上方一条 − 左方一条 + 左上角。左上角被减了两次，所以要补回一次。"],["b86",-1,"第 0 行 / 第 0 列"],["b87",-1,"全 0 的边界。x1 = 1 时 x1-1 = 0，公式照样成立，不用写特判。"],["b88",-1,"long long"],["b89",-1,"1000 × 1000 的格子、每格到 10⁹ 时，矩形和能到 10¹⁵，int 装不下。"],["b90",-1,"二维差分"],["b91",-1,"矩形加 v 是四个角：左上、右下加 v，右上、左下减 v——对角同号。还原时做一次二维前缀和。"],["b93",-1,"拿一段最小程序验证：3×3 表上问子矩阵"],["b94",-1,"这段程序在 1..9 的 3×3 表上建前缀和，再问 (2,2) 到 (3,3) 的和："],["b95",-1,"#include <bits/stdc++.h> using namespace std; long long a[4][4] = {{0, 0, 0, 0}, {0, 1, 2, 3}, {0, 4, 5, 6}, {0, 7, 8, 9}}; long long pre[4][4]; int main() { for (int i = 1; i <= 3; ++i) for (int j = 1; j <= 3; ++j) pre[i][j] = pre[i - 1][j] + pre[i][j - 1] - pre[i - 1][j - 1] + a[i][j]; // 子矩阵 (2,2) 到 (3,3)：5 + 6 + 8 + 9 = 28 long long s = pre[3][3] - pre[1][3] - pre[3][1] + pre[1][1]; cout << s << \"\\n\"; return 0; }"],["b96",-1,"输出 28：5 + 6 + 8 + 9 = 28。四行公式里没有一次循环，矩形多大都一样快。"],["b98",-1,"两条边界：符号靠代、第 0 行第 0 列必须存在"],["b99",-1,"符号不必背，拿 a = [[1,2],[3,4]] 代一遍：pre[2][2] = 3 + 4 − 1 + 4 = 10 = 1+2+3+4，四个符号错一个都对不上。"],["b100",-1,"二维里最容易忘的是「第 0 行 / 第 0 列也要存在」。数组开成 n × m 就写不下 pre[0][j]，公式会整体错位。"],["b101",-1,"读入 n 与 a[1..n]。这张图用 a = 4 3 2 1 走一遍"],["b102",-1,"pre[0] = 0;哨兵：它是「前 0 个数的和」，让 l = 1 时的 pre[l-1] 仍然有定义"],["b103",-1,"for (int i = 1; i <= n; ++i) pre[i] = pre[i-1] + a[i];逐格累加：pre 变成 0 4 7 9 10，每一格都等于左边一格加上本格的 a[i]"],["b104",-1,"?l 等于 1 吗？"],["b105",-1,"cout << pre[r] - pre[l - 1] << \"\\n\";查询只看两格，与区间长度无关：问 [2,3] 就是 9 − 4 = 5"],["b106",-1,"整张图只有一处循环（建表）和一处减法（查询）：n 次加法，换 m 次 O(1) 询问"],["b107",-1,"例题 · 求区间和 · 洛谷 P8218 普及-"],["b108",-1,"给定 n 个正整数 a₁, a₂, …, aₙ 和 m 个区间 [lᵢ, rᵢ]，分别求这 m 个区间的区间和。"],["b109",-1,"输入：第一行一个正整数 n；第二行 n 个正整数；第三行一个正整数 m；接下来 m 行，每行两个正整数 l、r，满足 1 ≤ l ≤ r ≤ n。输出：共 m 行，第 i 行为第 i 组询问的答案。"],["b110",-1,"数据范围：1 ≤ n, m ≤ 10⁵，1 ≤ aᵢ ≤ 10⁴。"],["b111",-1,"样例"],["b112",-1,"输入： 4 4 3 2 1 2 1 4 2 3 输出： 10 5"],["b113",-1,"const int MAXN = 100005; // n ≤ 10^5，多留几个位置 long long pre[MAXN]; // pre[i] = a[1] + ... + a[i] int main() { ios::sync_with_stdio(false); // 10^5 个数 + 10^5 行输出，先提速 cin.tie(nullptr);"],["b114",-1,"MAXN 取 100005：pre 的下标最大到 n = 10⁵，多开 5 个位置是习惯，改大 n 时不容易忘。数组放全局还有另一个好处——10⁵ 个 long long 约 800 KB，放栈上可能直接溢出。"],["b115",-1,"pre 的类型按「和」的量级选，不按 a 的类型选：n = 10⁵、aᵢ = 10⁴ 时和是 10⁹，已经贴着 int 上限，一律用 long long。两行提速是因为本题输入 10⁵ 个数、输出最多 10⁵ 行，不关同步可能多花几百毫秒，正好卡在时限边缘。"],["b116",-1,"int n; cin >> n; pre[0] = 0; // 哨兵：前 0 个数的和 for (int i = 1; i <= n; ++i) { long long x; cin >> x; pre[i] = pre[i - 1] + x; // 边读边建表，省掉 a 数组 }"],["b117",-1,"pre[0] = 0 是哨兵：全局数组本来就是 0，但显式写出来语义清楚，哪天改成局部数组也不会忘。"],["b118",-1,"pre[i] = pre[i - 1] + x 边读边累加，a 数组整个省掉——a[i] 只用来建一次表，没必要存。i 必须从小到大，因为这一格依赖左边一格。"],["b119",-1,"int m; cin >> m; while (m--) { int l, r; cin >> l >> r; cout << pre[r] - pre[l - 1] << '\\n'; }"],["b120",-1,"while (m--) 循环 m 次；m 减到 0 时退出，循环体里拿到的正是本轮编号。pre[r] - pre[l - 1] 是全部算法：r 之前的所有数，减去 l 之前的所有数，剩下的正好是 a[l..r]。"],["b121",-1,"输出用 '\\n' 不用 endl：endl 每次都 flush，10⁵ 行会明显拖慢。"],["b122",-1,"四段拼起来，再加上 return 0;，就是能直接提交的一份程序："],["b123",-1,"#include <bits/stdc++.h> using namespace std; const int MAXN = 100005; // n ≤ 10^5，多留几个位置 long long pre[MAXN]; // pre[i] = a[1] + ... + a[i] int main() { ios::sync_with_stdio(false); // 10^5 个数 + 10^5 行输出，先提速 cin.tie(nullptr); int n; cin >> n; pre[0] = 0; // 哨兵：前 0 个数的和 for (int i = 1; i <= n; ++i) { long long x; cin >> x; pre[i] = pre[i - 1] + x; // 边读边建表，省掉 a 数组 } int m; cin >> m; while (m--) { int l, r; cin >> l >> r; cout << pre[r] - pre[l - 1] << '\\n'; } return 0; }"],["b124",-1,"#include <bits/stdc++.h> 是万能头，一次顶掉 iostream、climits 这些零碎头文件；const int MAXN 和 pre 都写在 main 外面，走的是静态区，10⁵ 个 long long 不会把栈撑爆。"],["b125",-1,"return 0; 告诉评测机程序正常结束：退出时输出缓冲区被整体刷出去，评测机这才开始逐字节比对答案。"],["b126",-1,"把这段代码和上一节的三段式对照一下：读入、建表、回答，各是一段直白的 for 或 while，没有任何嵌套。真正需要想清楚的只有「下标从几开始」和「和用什么类型存」这两件事。"],["b127",-1,"题型特征：数组静态不变、只问区间和，先想前缀和；改成「多次区间加、最后统一输出」，先想差分。判据只有一句：这个量是要反复「查」还是要反复「改」。"],["b128",-1,"复杂度：建表 O(n)，每次询问 O(1)，总时间 O(n + m)，空间 O(n)。n = m = 10⁵ 时约 2×10⁵ 次运算，比朴素解法的 5×10⁹ 小四个数量级。"],["b129",-1,"下标从 0 开始却照抄 pre[r] - pre[l-1]：整体偏移一位，l = 0 时还会读到 pre[-1]。"],["b130",-1,"忘了 pre[0] = 0：换成局部数组或 vector 后它是随机值，所有从第一个数开始的询问全错。"],["b131",-1,"用 int 存和：本题 10⁹ 侥幸能过，aᵢ 改成 10⁵ 就是 10¹⁰，溢出成负数。"],["b132",-1,"差分数组只开 n 个：r = n 时要写 d[n+1]，必然越界。"],["b133",-1,"可扩展：区间异或同样能用前缀和（异或自己是 0，有逆元）；区间最大值不行（max 没有逆运算），要换 ST 表或线段树。"],["b134",1,"四个最容易踩的坑（都写清症状）"],["b135",-1,"下标从 0 开始：数据放 a[0..n-1]，公式却照抄 pre[r] - pre[l-1]。症状是整体偏移一位，某些询问恰好对、大部分错；l = 0 时还会访问 pre[-1]。修法：统一 1 基，pre[0] 空着当哨兵。"],["b136",-1,"忘了 pre[0] = 0：全局数组默认清零，看起来没事；一旦换成局部数组或 vector，pre[0] 就是随机值。症状是所有从第一个数开始的询问全错，其它询问正常。"],["b137",-1,"用 int 存和：n = 10⁵、aᵢ = 10⁴ 时和是 10⁹，int 上限约 2.1×10⁹，本题侥幸能过；换成 aᵢ ≤ 10⁵ 就是 10¹⁰，溢出成负数。症状是小数据全对、大数据输出负数。"],["b138",-1,"差分数组只开 n 个：区间右端点 r = n 时要写 d[n+1]，只开 n 个必然越界。症状是 RE，或者悄悄改到隔壁变量上、表现为随机 WA。"],["b139",2,"自己动手复现（合上这一页再写）"],["b140",-1,"复现不是把代码抄一遍，而是把「为什么这么写」重新说一遍。按下面四步做，每步都先合上页面。"],["b141",-1,"第一遍：只看例题的输入输出，自己写出读入、建表、回答三段；写完再对照。重点看 pre[0] 和 l - 1。"],["b142",-1,"第二遍：把 a 换成含负数的数据，分别测 l = 1、l = r、r = n 三种边界，答案要和手算一致。"],["b143",-1,"第三遍：把代码改成「先读入全部询问、再统一输出」，比较两版的差别，判断这样做有没有必要。"],["b144",-1,"第四遍：把例题改成差分版——读入 n 个数，p 次区间加，最后输出整个数组；感受两次单点修改替换一次循环。"],["b145",3,"数学补给 · 一次减法为什么能代替一次循环"],["b146",-1,"前缀和的全部依据，是加法的一个小学性质：整体等于部分之和。把 a[1..r] 拆成两段："],["b147",-1,"a[1] + … + a[r] = (a[1] + … + a[l-1]) + (a[l] + … + a[r])"],["b148",-1,"移项，中间那一段就等于两块前缀相减："],["b149",-1,"a[l] + … + a[r] = pre[r] - pre[l-1]"],["b150",-1,"写成 pre 的语言：pre[r] 里含有 a[1..l-1] 这一整段，pre[l-1] 恰好也是这一整段，逐项相减时它们完全抵消，只剩 a[l..r]。所以查询的代价从「区间长度 len 次加法」变成「两次查表 + 一次减法」，与 len 无关。"],["b151",-1,"能「抵消」，前提是每项都有逆元。加法有（减法是加相反数），所以区间和可以这样算；异或也有（一个数异或自己等于 0），所以区间异或同样可以；max、min 没有逆运算，知道两段前缀的最大值推不出区间最大值，所以区间最大值不能用前缀和，要用 ST 表。"],["b152",-1,"差分是同一件事的镜像。记 S 为「前缀和」算子、D 为「差分」算子，则 D(S(a)) = a、S(D(a)) = a。在 a 上做一次长度为 len 的区间加，要改 len 个位置；换到 D(a) 上，只有 l 和 r+1 两个位置发生变化。这就是「两次单点修改替换一次循环」的全部道理。"],["b153",-1,"做法"],["b154",-1,"预处理"],["b155",-1,"每次操作"],["b156",-1,"n = q = 10⁵ 时"],["b157",-1,"朴素循环"],["b159",-1,"O(len)"],["b160",-1,"约 5×10⁹ 次加法，TLE"],["b161",-1,"前缀和"],["b162",-1,"O(n) 建表"],["b163",-1,"O(1) 查询"],["b164",-1,"2×10⁵ 次，AC"],["b165",-1,"差分"],["b166",-1,"O(n) 还原"],["b167",-1,"O(1) 修改"],["b168",-1,"2×10⁵ 次，AC"],["b169",-1,"最后留一条判断标准：拿到题先看「区间上要做的事」可不可逆。可逆就用前缀和把区间变成两个端点，不可逆就换数据结构。"],["b170",4,"举一反三 · 想清楚这些再往下走"],["b171",-1,"如果整道题只有一次询问，还值得先建一张前缀和表吗？用 n 和区间长度 len 说明什么时候划算、什么时候不划算。 想好了？点开核对思路与解析结论：只有一次询问时不值得。直接累加是 O(len)，建表是 O(n) + O(1)，而 len ≤ n，所以建表只会更慢，还多开一个数组。前缀和赚的是「询问次数 q」：朴素总代价 O(q·len)，前缀和 O(n + q)，只有 q 大到 n + q 小于 q·len 时才回本，q 越大、区间越长越明显。常见错路：把「前缀和查询 O(1)」当成「前缀和永远更快」，给一次询问也建表；反过来，q = 10⁵ 还用 for 一遍一遍加，直接 TLE。"],["b172",-1,"区间异或查询能不能用前缀和？区间最大值为什么不能？请从「有没有逆运算」回答，并说出最大值的正确做法需要预处理什么。 想好了？点开核对思路与解析异或可以。令 pre[i] = a[1] ^ a[2] ^ … ^ a[i]，则区间 [l, r] 的异或 = pre[r] ^ pre[l-1]：前缀里多出来的部分出现两次，自己把自己消成 0。加法也可以，靠的是减法。最大值不行：max 没有逆运算，知道 max(a[1..r]) 和 max(a[1..l-1]) 推不出 max(a[l..r])。反例 a = [5, 1, 3]，区间 [2,3] 的最大值是 3，但两个前缀最大值都是 5。正确做法是 ST 表：st[k][i] 表示从 i 起 2^k 个数的最大值，O(n log n) 预处理、O(1) 查询；也可以用线段树。常见错路：用 pre[r] - pre[l-1] 求最大值，或把两个前缀 max 相减、取较小值。"],["b173",-1,"差分数组能不能支持「改一次、马上问一次」？如果不能，缺的那块工具是什么？请说清差分适合的处理顺序。 想好了？点开核对思路与解析不能。差分只把「修改」变便宜了：一次区间加是 O(1)；但每次查询都要从头做一遍前缀和还原，O(n)。q 次「改完就问」总代价还是 O(nq)，和朴素没区别。差分的适用前提是「所有修改先记下来，最后统一还原一次」。要做到边改边问，得用树状数组或线段树，它们把区间加、区间求和都压到 O(log n)。常见错路：每次询问都重建一遍还原数组，以为查询还是 O(1)；或者把差分数组直接当答案输出。"],["b174",-1,"给 n 个整数，问有多少个子区间的和能被 7 整除。把前缀和对 7 取模之后，答案为什么等于「相同余数的前缀两两配对」？写出计数式，并说明 pre[0] 为什么不能漏。 想好了？点开核对思路与解析记 pre[i] = (a[1] + … + a[i]) mod 7。a[l..r] 的和 ≡ pre[r] - pre[l-1] (mod 7)，它能被 7 整除当且仅当 pre[r] = pre[l-1]。于是问题变成：在 pre[0..n] 这 n+1 个数里，同余的两两能配成多少对，答案是 Σ C(cnt[k], 2)，k = 0..6，cnt[k] 是余数 k 出现的次数。pre[0] = 0 必须算进去：它代表所有「从第 1 个数开始」的区间，漏了它，前缀本身就能被 7 整除的那些区间会全部丢掉。常见错路：只数数组里 7 的倍数，那只覆盖长度为 1 的区间；以及忘记 pre[0]，或者把端点算错一位。"],["b175",5,"过关自测（全部做到再往下）"],["b176",-1,"关掉页面，能默写出建表与查询各一行，并解释 pre[0] 的作用。"],["b177",-1,"给 a = 3 1 4 1 5，手算 pre[0..5]，再用公式求 [2,4] 的和，和手算结果对上。"],["b178",-1,"对「把 [3,6] 每个数加 2」这个操作，写出差分数组上的两处修改，并说出 r = n 时会发生什么。"],["b179",-1,"能讲清为什么区间最大值不能照搬前缀和，正确做法是什么。"],["b180",-1,"能把例题改写成「p 次区间加、最后输出整个数组」的差分版，并跑过样例。"],["b181",6,"延伸阅读 / 参考"],["b182",-1,"《算法竞赛进阶指南》0x03 前缀和与差分：把区间操作换成端点操作"],["b183",-1,"OI Wiki「前缀和 & 差分」词条，二维容斥的图例很直观"],["b184",-1,"cp-algorithms 的 Prefix Sums 一节，英文表述更接近竞赛术语"],["b185",-1,"洛谷 P8218、P2367、P2280 三题的题解区，正好覆盖本节的一维与二维"],["b186",7,"挑战题 · 语文成绩"],["b187",-1,"有 n 个学生，给出初始成绩 a₁…aₙ。接下来 p 次操作，每次把第 x 个到第 y 个学生的成绩每人加 z 分。所有操作结束后，输出全班的最低分。"],["b188",-1,"输入：第一行 n、p；第二行 n 个整数表示初始成绩；接下来 p 行，每行 x、y、z，表示给第 x 到第 y 个学生每人加 z 分。"],["b189",-1,"输出：一行一个整数，即最终的最低分。"],["b190",-1,"数据范围：n ≤ 5×10⁶，p ≤ n，初始成绩 ≤ 100，z ≤ 100。"],["b191",-1,"输入： 3 2 1 1 1 1 2 1 2 3 1 输出： 2"],["b192",-1,"每次给一个区间加 z，如果真去 for 一遍，p 次就是 O(np)。n 能到 5×10⁶，p 也能到这个量级，乘法一算就知道过不了。"],["b193",-1,"把「区间加」拆成两个「单点加」：一个在左端点开始生效，一个在右端点之后立刻撤销。最后从头扫一遍就能还原。"],["b194",-1,"还原的过程同时也是取最小值的过程，不必把最终成绩存进第三个数组。n = 5×10⁶ 时，少一个 int 数组就少 20 MB。"],["b195",-1,"朴素做法：每次操作 for 一遍 [x, y]。p 和 n 都能到 5×10⁶，最坏 2.5×10¹³ 次加法，必然超时。 换成差分。整段程序只有三段：建差分、2p 次单点修改、一遍前缀和还原并取最小值。中间那 p 次操作每次都只碰两个格子，与区间长度无关，这是复杂度从 O(np) 降到 O(n+p) 的全部原因。 建差分时不必先存 a：读入第 i 个数时，减去上一个读到的数就得到 d[i]，一个数组就够了。这样 n = 5×10⁶ 时内存只要 20 MB。 z 的符号不用管：z 为负时 d[x] += z 就是在做减法，算法一字不改。最后边还原边取 min，也不需要额外数组。 复杂度：O(n + p)，5×10⁶ 级别在 1 秒内能跑完。注意 d[y+1] 在 y = n 时会写到 n+1，数组必须多开。"],["b196",-1,"参考代码 #include <bits/stdc++.h> using namespace std; const int MAXN = 5000005; // n ≤ 5×10^6；还要用 d[n+1]，多留几位 int d[MAXN]; int main() { ios::sync_with_stdio(false); // 5×10^6 个整数，必须提速 cin.tie(nullptr); int n, p; cin >> n >> p; int last = 0; for (int i = 1; i <= n; ++i) { int x; cin >> x; d[i] = x - last; // 边读边差分，a 数组整个省掉 last = x; } while (p--) { int x, y, z; cin >> x >> y >> z; d[x] += z; // 从 x 起每人多 z 分 d[y + 1] -= z; // 从 y+1 起撤掉这层 z } int cur = 0, mn = INT_MAX; for (int i = 1; i <= n; ++i) { cur += d[i]; // 还原成真实成绩 if (cur < mn) mn = cur; // 边还原边取最低分 } cout << mn << '\\n'; return 0; } 关键片段拆解 …"],["b197",8,"挑战 2 · 难度高一级，要把二维前缀和与边界一起想清楚"],["b198",-1,"这题的数据范围不大，却埋了三个坑：坐标从 0 开始、正方形的边上不算命中、整张 5000×5000 的表要放进内存。独立做出来，说明前缀和这一块真的过关了；做完记得在侧边栏勾上 🌟。"],["b199",9,"挑战 2 · 激光炸弹"],["b200",-1,"地图上有 n 个目标，第 i 个目标在整数坐标 (xᵢ, yᵢ)，价值 vᵢ。一颗激光炸弹可以摧毁一个边长为 m、边与坐标轴平行的正方形内的所有目标；若目标恰好落在正方形的边上，则不会被摧毁。同一位置可能有多个目标。"],["b201",-1,"输入：第一行 n、m；接下来 n 行，每行三个整数 x、y、v。"],["b202",-1,"输出：一个整数，表示一颗炸弹最多能摧毁的总价值。"],["b203",-1,"数据范围：1 ≤ n ≤ 10⁴，0 ≤ xᵢ, yᵢ ≤ 5000，1 ≤ m ≤ 5000，1 ≤ vᵢ < 100；答案不超过 32767。"],["b204",-1,"输入： 2 1 0 0 1 1 1 1 输出： 1"],["b205",-1,"坐标范围只有 0..5000，目标只有 10⁴ 个：把所有目标按坐标堆进一张 5005×5005 的表，代价是可以接受的。"],["b206",-1,"「一块正方形内的权值和」在二维前缀和上是 O(1) 的。剩下的问题只是：这张表怎么建，右下角枚举到哪。"],["b207",-1,"边长是 m，边界上的点不算命中。把正方形的左边放在 x-0.5 的位置想一想：内部最多能装下多少个整数 x 坐标？这决定了窗口到底取几格。"],["b208",-1,"坐标从 0 开始，而前缀和习惯从 1 开始——所有坐标先 +1，第 0 行、第 0 列就空出来当哨兵了。数组下标至少要能取到 5001，开 5005 比较稳。"],["b209",-1,"第一步，把目标堆进表里。坐标范围 0..5000，所以开一张 5005×5005 的 int 表，读到一个目标就在对应格子上加 v。同一位置多个目标直接累加，这一步不能覆盖。 第二步，坐标整体 +1。这样目标落在 1..5001，第 0 行与第 0 列天然全 0，前缀和公式在 x = 1、y = 1 时不用特判。 第三步，二维前缀和建表：s[i][j] += s[i-1][j] + s[i][j-1] - s[i-1][j-1]。这是就地覆盖，建完之后 s[i][j] 就是左上角到 (i,j) 的矩形和。 第四步，枚举右下角。边长 m 的正方形，边界不算命中，把四条边放在相邻整数之间，内部恰好能容纳 m 个连续整数坐标。所以右下角取 (i, j)、i, j ∈ [m, 5001] 时，窗口是 [i-m+1, i] × [j-m+1, j]，正好 m×m 个整点。 第五步，用容斥取和：s[i][j] - s[i-m][j] - s[i][j-m] + s[i-m][j-m]，和所有窗口比大小。i 从 m 开始，保证 i-m ≥ 0，不会读到负下标。 复杂度：建表 5001² ≈ 2.5×10⁷ 次加法，枚举同样量级；n = 10⁴ 可以忽略。内存 5005²×4B ≈ 100 MB，必须放全局静态区。"],["b210",-1,"参考代码 #include <bits/stdc++.h> using namespace std; const int C = 5001; // 坐标 0..5000，整体 +1 后最大是 5001 int s[5005][5005]; // 5005 × 5005 × 4B ≈ 100 MB，必须放全局 int main() { ios::sync_with_stdio(false); cin.tie(nullptr); int n, m; cin >> n >> m; for (int i = 1; i <= n; ++i) { int x, y, v; cin >> x >> y >> v; s[x + 1][y + 1] += v; // 同一位置可能叠多个目标 } for (int i = 1; i <= C; ++i) for (int j = 1; j <= C; ++j) s[i][j] += s[i - 1][j] + s[i][j - 1] - s[i - 1][j - 1]; int ans = 0; for (int i = m; i <= C; ++i) for (int j = m; j <= C; ++j) { int t = s[i][j] - s[i - m][j] - s[i][j - m] + s[i - m][j - m]; if (t >…"]]}];
